SET SESSION ROLE postgres;
BEGIN TRANSACTION READ ONLY;
SELECT json_build_object(
  'database',current_database(),
  'server_version',current_setting('server_version'),
  'extensions',(SELECT coalesce(json_agg(json_build_object('schema',n.nspname,'name',e.extname,'version',e.extversion) ORDER BY n.nspname,e.extname),'[]'::json) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace),
  'tables',(SELECT coalesce(json_agg(json_build_object('schema',n.nspname,'name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'columns',(SELECT json_agg(json_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'generated',a.attgenerated,'identity',a.attidentity,'default_md5',md5(pg_get_expr(d.adbin,d.adrelid))) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)) ORDER BY n.nspname,c.relname),'[]'::json) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND ((n.nspname='public' AND (c.relname IN ('user_profiles','chat_messages','chat_threads','oc_profiles','conversations','activation_codes','usage','usage_logs','request_logs','thanks','thanks_likes','orders','profiles','email_codes') OR c.relname='account_deletion_jobs' OR c.relname LIKE 'sunland\_phone\_%' OR c.relname LIKE 'sunland\_otp\_%')) OR (n.nspname='auth' AND c.relname IN ('users','identities')) OR (n.nspname='storage' AND c.relname IN ('buckets','objects')))),
  'indexes',(SELECT coalesce(json_agg(json_build_object('schema',schemaname,'table',tablename,'name',indexname,'definition',indexdef) ORDER BY schemaname,tablename,indexname),'[]'::json) FROM pg_indexes WHERE (schemaname='public' AND (tablename IN ('user_profiles','chat_messages','chat_threads','oc_profiles','conversations','activation_codes','usage','usage_logs','request_logs','thanks','thanks_likes','orders','profiles','email_codes') OR tablename='account_deletion_jobs' OR tablename LIKE 'sunland\_phone\_%' OR tablename LIKE 'sunland\_otp\_%')) OR (schemaname='auth' AND tablename IN ('users','identities')) OR (schemaname='storage' AND tablename IN ('buckets','objects'))),
  'constraints',(SELECT coalesce(json_agg(json_build_object('schema',n.nspname,'table',c.relname,'name',con.conname,'type',con.contype,'validated',con.convalidated,'definition',pg_get_constraintdef(con.oid)) ORDER BY n.nspname,c.relname,con.conname),'[]'::json) FROM pg_constraint con JOIN pg_class c ON c.oid=con.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE (n.nspname='public' AND (c.relname IN ('user_profiles','chat_messages','chat_threads','oc_profiles','conversations','activation_codes','usage','usage_logs','request_logs','thanks','thanks_likes','orders','profiles','email_codes') OR c.relname='account_deletion_jobs' OR c.relname LIKE 'sunland\_phone\_%' OR c.relname LIKE 'sunland\_otp\_%')) OR (n.nspname='auth' AND c.relname IN ('users','identities')) OR (n.nspname='storage' AND c.relname IN ('buckets','objects'))),
  'functions',(SELECT coalesce(json_agg(json_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'definition_md5',md5(pg_get_functiondef(p.oid)),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'security_definer',p.prosecdef) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),'[]'::json) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f'),
  'triggers',(SELECT coalesce(json_agg(json_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled) ORDER BY n.nspname,c.relname,t.tgname),'[]'::json) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND ((n.nspname='public' AND (c.relname IN ('user_profiles','chat_messages','chat_threads','oc_profiles','conversations','activation_codes','usage','usage_logs','request_logs','thanks','thanks_likes','orders','profiles','email_codes') OR c.relname='account_deletion_jobs' OR c.relname LIKE 'sunland\_phone\_%' OR c.relname LIKE 'sunland\_otp\_%')) OR (n.nspname='auth' AND c.relname IN ('users','identities')) OR (n.nspname='storage' AND c.relname IN ('buckets','objects')))),
  'policies',(SELECT coalesce(json_agg(json_build_object('schema',schemaname,'table',tablename,'name',policyname,'permissive',permissive,'command',cmd,'roles',roles,'using',qual,'with_check',with_check) ORDER BY schemaname,tablename,policyname),'[]'::json) FROM pg_policies WHERE (schemaname='public' AND (tablename IN ('user_profiles','chat_messages','chat_threads','oc_profiles','conversations','activation_codes','usage','usage_logs','request_logs','thanks','thanks_likes','orders','profiles','email_codes') OR tablename='account_deletion_jobs' OR tablename LIKE 'sunland\_phone\_%' OR tablename LIKE 'sunland\_otp\_%')) OR (schemaname='auth' AND tablename IN ('users','identities')) OR (schemaname='storage' AND tablename IN ('buckets','objects')))
);
COMMIT;
